MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    bounds = [[n] * n for _ in range(n)]
    for i in range(2, len(data), 3):
        l, r, x = data[i]-1, data[i+1]-1, data[i+2]-1
        if l == r:
            print(0)
            return
        if r < bounds[l][x]:
            bounds[l][x] = r
    for l in range(n-2, -1, -1):
        row, nxt = bounds[l], bounds[l+1]
        for k in range(l, n):
            if nxt[k] < row[k]:
                row[k] = nxt[k]
    inv = [0] * (n+1)
    inv[1] = 1
    for i in range(2, n+1):
        inv[i] = MOD - (MOD//i) * inv[MOD%i] % MOD
    dp = [[0]*(n+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][i] = 1
    for l in range(n-1, -1, -1):
        row = dp[l]
        bound = bounds[l]
        for r in range(l, n):
            end = r+1
            total = 0
            for k in range(l, end):
                if r < bound[k]:
                    total += row[k] * dp[k+1][end]
            row[end] = (total % MOD) * inv[end-l] % MOD
    ans = dp[0][n]
    for i in range(2, n+1):
        ans = ans*i % MOD
    print(ans)

if __name__ == '__main__':
    solve()

