import sys
from collections import deque
from array import array

MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    indeg = [0] * n
    for p in a:
        indeg[p] += 1
    queue = deque(i for i in range(n) if indeg[i] == 0)
    dp = [None] * n
    while queue:
        v = queue.popleft()
        p = a[v]
        cur = dp[v]
        target = dp[p]
        if target is None:
            if cur is None:
                cur = array('I', range(1, m + 1))
            else:
                s = 0
                for j in range(m):
                    s += cur[j]
                    if s >= MOD:
                        s -= MOD
                    cur[j] = s
            dp[p] = cur
        elif cur is None:
            for j in range(m):
                target[j] = target[j] * (j + 1) % MOD
        else:
            s = 0
            for j in range(m):
                s += cur[j]
                if s >= MOD:
                    s -= MOD
                target[j] = target[j] * s % MOD
        dp[v] = None
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)
    answer = 1
    for start in range(n):
        if indeg[start] == 0:
            continue
        v = start
        product = None
        while indeg[v]:
            indeg[v] = 0
            cur = dp[v]
            if cur is not None:
                if product is None:
                    product = cur
                else:
                    for j in range(m):
                        product[j] = product[j] * cur[j] % MOD
            dp[v] = None
            v = a[v]
        ways = m if product is None else sum(product) % MOD
        answer = answer * ways % MOD
    print(answer)

if __name__ == '__main__':
    solve()

