        weights={}
        for g in gaps:
            r=pow(p,g,MOD)
            w=[1]*(total+1)
            for h in range(1,total+1):
                w[h]=w[h-1]*r%MOD
            weights[g]=w
        dp=[1]
        for t,(i,e) in enumerate(events):
            g=events[t+1][0]-i if t+1<len(events) else n-i
            w=weights[g]
            length=len(dp)
            nd=[0]*e+dp
            for h in range(e,length):
                nd[h-e]+=dp[h]
            for h in range(1,len(nd)):
                nd[h]=nd[h]*w[h]%MOD
            r=pow(p,i,MOD)
