import sys
from math import gcd


def solve(data):
    it = iter(data)
    n, budget = next(it), next(it)
    processes = []
    upper = budget * 100 + 1
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # S has at least as much capacity per yen as T.
        if a * q < b * p:
            a, p, b, q = b, q, a, p
        # a/gcd(a,b) T machines can be replaced by b/gcd(a,b)
        # S machines without increasing cost or changing capacity.
        options = [(y * b, y * q) for y in range(a // gcd(a, b))]
        processes.append((a, p, options))
        upper = min(upper, budget * a // p + 1)

    low = 0
    while upper - low > 1:
        target = (low + upper) // 2
        total = 0
        for a, p, options in processes:
            best = ((target + a - 1) // a) * p
            for capacity, cost in options:
                remaining = target - capacity
                if remaining > 0:
                    cost += ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                break
        if total <= budget:
            low = target
        else:
            upper = target
    return low


if __name__ == '__main__':
    print(solve(list(map(int, sys.stdin.buffer.read().split()))))

