class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # steps[x] counts the operations needed to reduce x to 1.
        steps = [0] * (length + 1)
        for x in range(2, length + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # dp[j]: prefixes strictly below s's prefix with j set bits.
        dp = [0] * (length + 1)
        ones = 0
        for i, bit in enumerate(s):
            for j in range(i + 1, 0, -1):
                dp[j] = (dp[j] + dp[j - 1]) % mod
            if bit == '1':
                # Leave the equal prefix by choosing zero here.
                dp[ones] = (dp[ones] + 1) % mod
                ones += 1

        # Exclude zero; one operation maps each other number to its popcount.
        return sum(
            dp[j] for j in range(1, length + 1) if steps[j] < k
        ) % mod

