def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, k = data[:3]
    x = data[3:]

    changes = sum(x[i] != x[i + 1] for i in range(m - 1))
    degree = n - (m * k - 1 + changes)
    if degree < 0:
        print(0)
        return

    dp = [0] * (degree + 1)
    dp[0] = 1

    for j in range(1, k):
        for _ in range(m):
            for i in range(1, degree + 1):
                dp[i] = (dp[i] + j * dp[i - 1]) % MOD

    if k > 2:
        for _ in range(changes):
            for i in range(1, degree + 1):
                dp[i] = (dp[i] + (k - 2) * dp[i - 1]) % MOD

    factorial = 1
    for j in range(1, k):
        factorial = factorial * j % MOD

    print(dp[degree] * pow(factorial, m, MOD) % MOD)


