from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        remaining = list(range(1, n + 1))
        odds, evens = (n + 1) // 2, n // 2
        answer = []
        previous = -1
        while remaining:
            for i, value in enumerate(remaining):
                parity = value % 2
                if parity == previous:
                    continue
                o = odds - parity
                e = evens - (1 - parity)
                if parity == 1:
                    feasible = e == o or e == o + 1
                else:
                    feasible = o == e or o == e + 1
                if not feasible:
                    continue
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    remaining.pop(i)
                    odds, evens = o, e
                    previous = parity
                    break
            else:
                return []
        return answer

