    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        weights = [(powers[i] + powers[n - 1 - i]) % k if i != n - 1 - i else powers[i] for i in range(half)]
        possible = [0] * (half + 1)
        possible[half] = 1
        full = (1 << k) - 1
        for i in range(half - 1, -1, -1):
            mask = possible[i + 1]
            reach = 0
            for d in range(10):
                shift = d * weights[i] % k
                reach |= ((mask << shift) | (mask >> (k - shift))) & full
            possible[i] = reach
        answer = ['0'] * n
        remainder = 0
        for i in range(half):
            for d in range(9, 0 if i == 0 else -1, -1):
