import sys

def winner(n, m, values):
    k = len(values)
    full = (1 << k) - 1
    lower = [0] * (1 << k)
    for i, x in enumerate(values):
        mask = 0
        for j, y in enumerate(values):
            if y < x:
                mask |= 1 << j
        lower[1 << i] = mask
    memo = bytearray(1 << (2 * k))

    def win(a, b):
        key = a | (b << k)
        known = memo[key]
        if known:
            return known == 2
        if not a:
            memo[key] = 1
            return False
        if not b:
            memo[key] = 2
            return True
        table = full ^ (a | b)
        remaining = a
        while remaining:
            card = remaining & -remaining
            remaining -= card
            hand = a ^ card
            if not win(b, hand):
                memo[key] = 2
                return True
            choices = table & lower[card]
            while choices:
                take = choices & -choices
                choices -= take
                if not win(b, hand | take):
                    memo[key] = 2
                    return True
        memo[key] = 1
        return False

    a = (1 << n) - 1
    b = ((1 << m) - 1) << n
    return win(a, b)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    print('Takahashi' if winner(n, m, data[3:]) else 'Aoki')

