import sys
import heapq


def even_scores(values):
    low = []
    high = []
    delta = 0
    scores = [0]
    push = heapq.heappush
    pop = heapq.heappop
    for i, x in enumerate(values, 1):
        if not low or x <= -low[0]:
            push(low, -x)
            delta -= x
        else:
            push(high, x)
            delta += x
        if len(low) > len(high) + 1:
            t = -pop(low)
            push(high, t)
            delta += 2 * t
        elif len(high) > len(low):
            t = pop(high)
            push(low, -t)
            delta -= 2 * t
        if i % 2 == 0:
            scores.append(delta)
    return scores


def solve(a):
    n = len(a)
    if n % 2 == 0:
        b = sorted(a)
        return sum(b[n // 2:]) - sum(b[:n // 2])
    left = even_scores(a)
    right = even_scores(reversed(a))
    m = n // 2
    return max(left[k] + right[m - k] for k in range(m + 1))


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(solve(data[1:]))


if __name__ == '__main__':
    main()

