    n=len(a)
    base=0
    if k>n-k:
        k=n-k
        for v in a: base^=v
    if k==0: return base
    best=0
    def dfs(start,left,value):
        nonlocal best
        if left==1:
            for i in range(start,n):
                candidate=value^a[i]
                if candidate>best: best=candidate
            return
        for i in range(start,n-left+1):
            dfs(i+1,left-1,value^a[i])
    dfs(0,k,base)
    return best

