import sys


def solve(n, a, b):
    ap = [i for i, c in enumerate(a) if c == 49]
    bp = [i for i, c in enumerate(b) if c == 49]
    if len(bp) > len(ap):
        return -1
    la, ra = ap[0], ap[-1]
    lb, rb = bp[0], bp[-1]

    nxt = [n] * (n + 1)
    q = n
    for i in range(n - 1, -1, -1):
        if a[i] == 49:
            q = i
        nxt[i] = q

    zr = []
    for x, y in zip(ap, ap[1:]):
        if y > x + 1:
            zr.append((x + 1, y - 1))
    gaps = [y - x - 1 for x, y in zip(bp, bp[1:])]

    def calc(parity):
        end = la + ((la - lb + parity) & 1)
        j = 0
        for gap in gaps:
            s = end + 1
            if gap:
                while j < len(zr):
                    l, r = zr[j]
                    st = max(s, l)
                    st += (st - s) & 1
                    if st + gap - 1 <= r:
                        break
                    j += 1
                else:
                    return 10**9
                s = st + gap
            if s > ra:
                return 10**9
            p = nxt[s]
            end = p + ((p - s) & 1)
        end = max(end, ra + ((ra - end) & 1))
        t = max(0, lb - la, end - rb)
        return t + ((t - parity) & 1)

    ans = min(calc(0), calc(1))
    return ans if ans < 10**9 else -1


def main():
    it = iter(sys.stdin.buffer.read().split())
    t = int(next(it))
    out = []
    for _ in range(t):
        n = int(next(it))
        a = next(it)
        b = next(it)
        out.append(str(solve(n, a, b)))
    print('\n'.join(out))


