import sys
import heapq

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[:2]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)
    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        values = []
        for _ in range(W // w):
            value = -heap[0]
            if value <= 0:
                break
            values.append(value)
            heapq.heapreplace(heap, 2 - value)
        if len(values) < 16:
            for value in values:
                for cap in range(W, w - 1, -1):
                    candidate = dp[cap - w] + value
                    if candidate > dp[cap]:
                        dp[cap] = candidate
        else:
            prefix = [0]
            for value in values:
                prefix.append(prefix[-1] + value)
            limit = len(values)
            for r in range(w):
                old = dp[r::w]
                size = len(old)
                new = [0] * size
                def compute(left, right, opt_left, opt_right):
                    if left > right:
                        return
                    mid = (left + right) // 2
                    start = max(opt_left, mid - limit)
                    end = min(mid, opt_right)
                    best = -1
                    arg = start
                    for k in range(start, end + 1):
                        candidate = old[k] + prefix[mid - k]
                        if candidate > best:
                            best = candidate
                            arg = k
                    new[mid] = best
                    compute(left, mid - 1, opt_left, arg)
                    compute(mid + 1, right, arg, opt_right)
                compute(0, size - 1, 0, size - 1)
                dp[r::w] = new
    print(dp[W])

if __name__ == '__main__':
    solve()

