def possible(s, t, k):
    n, m = len(s), len(t)
    if abs(n-m) > k:
        return False
    offset = k + 1
    size = 2*k + 3
    neg = -1000000
    prev = [neg] * size
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        return True
    prev[offset] = x
    for e in range(1, k+1):
        cur = [neg] * size
        for d in range(max(-e, -n), min(e, m)+1):
            idx = offset + d
            x = prev[idx]
            a = prev[idx] + 1
            if 0 <= a <= n and 0 <= a+d <= m and a > x:
                x = a
            a = prev[idx+1] + 1
            if 0 <= a <= n and 0 <= a+d <= m and a > x:
                x = a
            a = prev[idx-1]
            if 0 <= a <= n and 0 <= a+d <= m and a > x:
                x = a
            if x < 0:
                continue
            y = x+d
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            cur[idx] = x
        prev = cur
    return False

def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    print('Yes' if possible(data[1], data[2], k) else 'No')

if __name__ == '__main__':
    main()

