import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    freq = [0] * (n + 1)
    score = 0
    for x in a:
        if freq[x] == 0:
            score += 1
        freq[x] += 1
    seen = bytearray(n + 1)
    answer = 0
    for i in range(n - 1):
        x = a[i]
        if not seen[x]:
            seen[x] = 1
            score += 1
        freq[x] -= 1
        if freq[x] == 0:
            score -= 1
        if score > answer:
            answer = score
    print(answer)

