def brute(a):
    # Enumerate all subsets of intermediate landing positions.
    n = len(a)
    if n == 1:
        return 0
    ans = 0
    for mask in range(1 << max(0, n - 2)):
        path = [0] + [i for i in range(1, n - 1) if mask & (1 << (i - 1))] + [n - 1]
        ans = max(ans, sum((j-i)*a[i] for i,j in zip(path,path[1:])))
    return ans

