def brute(blocks,w):
    pos={i:p for i,p in enumerate(blocks)}
    death=[10**18]*len(blocks)
    for t in range(1,25):
        bottom=[i for i,(x,y) in pos.items() if y==1]
        if len(bottom)==w:
