def brute(s):
    t = '1' + s + '1'
    best = s.count('1')
    n = len(t)
    for l in range(1, n-1):
        for r in range(l+1, n):
            if t[l-1] != '0' or t[r] != '0' or any(c != '1' for c in t[l:r]):
                continue
            u = t[:l] + '0'*(r-l) + t[r:]
            for a in range(1, n-1):
                for b in range(a+1, n):
                    if u[a-1] == u[b] == '1' and all(c == '0' for c in u[a:b]):
                        v = u[:a] + '1'*(b-a) + u[b:]
                        best = max(best, v[1:-1].count('1'))
    return best
